  "    actual = parse_date(exif.get('dateTimeOriginal'))\n"
  "    zone = exif.get('timeZone')\n"
  '    if not actual or actual.tzinfo is None or not zone:\n'
  '        return False\n'
  '    return abs((actual - expected).total_seconds()) < 1 and zone_offset(zone, expected) == '
