  '            stack.enter_context(locked(config.companion_root))\n'
  '            now = datetime.now(timezone.utc)\n'
  '            index = hashcache.load(config.manifest_root)\n'
  '            previous = {}\n'
  '            for key in plan.bundles:\n'
  '                try:\n'
  '                    previous[key] = manifest.load(config.manifest_root / "insta360" / (key + '
  '".json"))\n'
  '                except (OSError, ImportFailure) as error:\n'
  '                    for item in plan.bundles[key]:\n'
  '                        fail(item, error)\n'
  '            # Hashes come from the index when the file is unchanged, are read up\n'
  '            # front only where a decision needs them before any upload (a bundle\n'
  '            # role the manifest already records), and are otherwise computed\n'
  '            # from the upload stream itself so a new file is read exactly once.\n'
