  '                for row in (value or {}).get("members", []):\n'
  '                    if isinstance(row, dict) and row.get("sha256"):\n'
  '                        recorded.add((key, row.get("role")))\n'
  '            upfront = [i for i in plan.assets if not i.error and not i.sha1 and (i.bundle, '
  'i.role) in recorded]\n'
  '            for position, item in enumerate(upfront, 1):\n'
  '                progress("[" + str(position) + "/" + str(len(upfront)) + "] hashing (manifest '
  'check): " + item.relative)\n'
  '                try:\n'
  '                    item.sha1, item.sha256 = hashes(item.path, item.fingerprint)\n'
  '                    item.hash_source = "read"\n'
  '                except (OSError, ImportFailure) as error:\n'
  '                    fail(item, error)\n'
  '            for item in plan.assets:\n'
  '                if not item.error and item.path.suffix.lower() not in api.media_types:\n'
  '                    fail(item, "Format is not supported by this Immich server")\n'
  '\n'
  '            def identity_checks():\n'
  '                # Same bytes cannot satisfy incompatible camera/visibility roles for\n'
  '                # one owner, nor two roles of one stack. Applied to every item whose\n'
  '                # hash is known, before upload where possible and again afterwards.\n'
  '                identities = {}\n'
  '                for item in plan.assets:\n'
  '                    if item.sha1 and not item.error:\n'
  '                        identities.setdefault(item.sha1, []).append(item)\n'
  '                for matches in identities.values():\n'
  '                    contracts = {(i.sha256, i.route, i.capture_time, '
  'tuple(sorted(i.expected.items()))) for i in matches}\n'
  '                    if len(contracts) > 1:\n'
  '                        for item in matches:\n'
  '                            fail(item, "Same Immich checksum has conflicting content, '
  'visibility or camera metadata")\n'
  '                    elif len({i.stack for i in matches if i.stack}) < sum(1 for i in matches if '
  'i.stack):\n'
  '                        for item in matches:\n'
  '                            fail(item, "Identical bytes in two members of one bundle/stack; '
  'needs review")\n'
  '\n'
  '            identity_checks()\n'
  '            for key, members in plan.bundles.items():\n'
  '                try:\n'
  '                    manifest.merge(previous.get(key), key, api.owner_id, config.api_url, '
